@font-face {
  font-family: "Inter Display";
  src: url("data:font/otf;base64,")
    format("opentype");
  font-weight: 700;
  font-display: swap;
}
@font-face {
  font-family: "Inter Display";
  src: url("data:font/otf;base64,")
    format("opentype");
  font-weight: 600;
  font-display: swap;
}
@font-face {
  font-family: "Open Sans";
  src: url("data:font/ttf;base64,")
    format("truetype");
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: "Open Sans";
  src: url("data:font/ttf;base64,")
    format("truetype");
  font-weight: 600;
  font-display: swap;
}

:root {
  --night: #04111f;
  --blue: #06182c;
  --blue-soft: #0a223b;
  --panel: #0b2743;
  --panel-2: #0d2d4d;
  --line: rgba(109, 177, 219, 0.22);
  --line-strong: rgba(109, 177, 219, 0.42);
  --cyan: #16afe7;
  --cyan-light: #55cef5;
  --ice: #f1f7fb;
  --muted: #9fb7ca;
  --muted-2: #7596b0;
  --shadow: 0 28px 75px rgba(0, 0, 0, 0.28);
}
* {
  box-sizing: border-box;
}
html {
  scroll-behavior: smooth;
  background: var(--night);
  scroll-padding-top: 84px;
}
body {
  margin: 0;
  background:
    radial-gradient(circle at 82% 8%, rgba(20, 89, 135, 0.16), transparent 30%),
    linear-gradient(180deg, var(--night) 0%, var(--blue) 33%, #071d33 100%);
  color: var(--ice);
  font-family: "Open Sans", "Segoe UI", sans-serif;
  font-size: 17px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}
img {
  display: block;
  max-width: 100%;
}
a {
  color: inherit;
  text-decoration: none;
}
button,
input,
textarea {
  font: inherit;
}
button {
  cursor: pointer;
}
button:disabled {
  cursor: wait;
  opacity: 0.72;
}
::selection {
  background: rgba(22, 175, 231, 0.35);
}
:focus-visible {
  outline: 2px solid var(--cyan-light);
  outline-offset: 4px;
}
.container {
  width: min(1380px, calc(100% - 64px));
  margin-inline: auto;
}
.section {
  padding: 108px 0;
  position: relative;
}
.section + .section {
  border-top: 1px solid rgba(130, 191, 226, 0.08);
}
.eyebrow {
  font:
    700 13px/1.2 "Open Sans",
    sans-serif;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--cyan-light);
}
.section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 48px;
  margin-bottom: 44px;
}
.section-title {
  font:
    700 clamp(40px, 3.7vw, 60px)/1.04 "Inter Display",
    sans-serif;
  letter-spacing: -0.038em;
  margin: 12px 0 0;
  max-width: 900px;
}
.section-lead {
  max-width: 620px;
  color: var(--muted);
  font-size: 18px;
  margin: 0 0 2px;
}
.glow-line {
  display: inline-block;
  width: 72px;
  height: 1px;
  margin-left: 14px;
  vertical-align: middle;
  background: linear-gradient(90deg, var(--cyan), transparent);
  box-shadow: 0 0 16px rgba(22, 175, 231, 0.8);
}
.button {
  min-height: 54px;
  padding: 0 22px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font:
    700 15px/1.2 "Inter Display",
    sans-serif;
  white-space: nowrap;
  transition:
    transform 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease,
    box-shadow 0.2s ease;
}
.button-primary {
  background: linear-gradient(180deg, #35c1ef, #119fdb);
  border-color: #45c9f4;
  color: #031424;
  box-shadow: 0 12px 35px rgba(22, 175, 231, 0.16);
}
.button-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 16px 45px rgba(22, 175, 231, 0.25);
}
.button-ghost {
  background: rgba(4, 19, 34, 0.58);
  color: var(--ice);
}
.button-ghost:hover {
  transform: translateY(-2px);
  border-color: rgba(85, 206, 245, 0.75);
  background: rgba(17, 72, 112, 0.28);
}
.button-small {
  min-height: 44px;
  padding-inline: 18px;
  font-size: 14px;
}
.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(4, 17, 31, 0.88);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid rgba(130, 191, 226, 0.11);
}
.nav-row {
  height: 84px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
}
.brand {
  width: 194px;
  display: flex;
  align-items: center;
  overflow: hidden;
}
.brand img {
  width: 100%;
  height: auto;
  mix-blend-mode: screen;
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 30px;
  font-size: 15px;
  color: #d9e7f0;
}
.nav-links > a:not(.button) {
  position: relative;
  padding: 27px 0;
}
.nav-links > a:not(.button)::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 19px;
  width: 0;
  height: 1px;
  background: var(--cyan);
  transition: width 0.2s ease;
}
.nav-links > a:not(.button):hover::after {
  width: 100%;
}
.mobile-toggle {
  display: none;
  width: 46px;
  height: 46px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: transparent;
  position: relative;
}
.mobile-toggle span {
  position: absolute;
  width: 20px;
  height: 1px;
  left: 12px;
  background: white;
  transition: 0.2s;
}
.mobile-toggle span:first-child {
  top: 18px;
}
.mobile-toggle span:last-child {
  top: 26px;
}
.mobile-toggle[aria-expanded="true"] span:first-child {
  top: 22px;
  transform: rotate(45deg);
}
.mobile-toggle[aria-expanded="true"] span:last-child {
  top: 22px;
  transform: rotate(-45deg);
}

.hero {
  min-height: 730px;
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  border-bottom: 1px solid rgba(130, 191, 226, 0.1);
}
.hero-copy {
  min-width: 0;
  padding: 78px max(36px, calc((100vw - 1380px) / 2)) 68px
    max(28px, calc((100vw - 1380px) / 2));
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
  z-index: 3;
  background: linear-gradient(
    90deg,
    #06182c 0%,
    #06182c 72%,
    rgba(6, 24, 44, 0.86) 90%,
    rgba(6, 24, 44, 0.16) 100%
  );
}
.hero-title {
  font:
    700 clamp(52px, 5vw, 82px)/1.01 "Inter Display",
    sans-serif;
  letter-spacing: -0.047em;
  margin: 15px 0 25px;
  max-width: 760px;
}
.hero-title span {
  color: var(--cyan-light);
}
.hero-subtitle {
  font-size: 20px;
  line-height: 1.55;
  color: #c4d7e5;
  max-width: 640px;
  margin: 0 0 19px;
}
.location-line {
  margin: 0 0 29px;
  color: #bfe8f7;
  font-size: 15px;
}
.location-line span {
  color: var(--cyan-light);
  font-size: 20px;
  margin-right: 7px;
}
.hero-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 27px;
}
.phone-row {
  display: flex;
  gap: 26px;
  flex-wrap: wrap;
}
.phone-row a {
  font:
    600 18px/1.35 "Open Sans",
    sans-serif;
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s;
}
.phone-row a:hover {
  border-color: var(--cyan-light);
}
.hero-note {
  font-size: 14px;
  color: var(--muted-2);
  margin: 18px 0 0;
}
.hero-media {
  min-width: 0;
  min-height: 730px;
  position: relative;
  overflow: hidden;
  background: #020b13;
}
.hero-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 100% center;
  transform: scale(1.06);
  transform-origin: right center;
  filter: none;
  z-index: 2;
}
.hero-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(6, 24, 44, 0.42),
      transparent 28%,
      rgba(0, 0, 0, 0.04)
    ),
    linear-gradient(180deg, transparent 70%, rgba(0, 0, 0, 0.22));
}
.image-label {
  position: absolute;
  z-index: 2;
  right: 25px;
  bottom: 24px;
  padding: 10px 13px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 9px;
  background: rgba(3, 14, 25, 0.62);
  backdrop-filter: blur(10px);
  font-size: 12px;
  color: #cbdce8;
}

.value-section {
  padding: 66px 0;
  background: linear-gradient(180deg, #071b31, #06182c);
  border-bottom: 1px solid rgba(130, 191, 226, 0.1);
}
.value-layout {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 70px;
  align-items: center;
}
.value-title {
  font:
    600 clamp(30px, 2.4vw, 42px)/1.12 "Inter Display",
    sans-serif;
  letter-spacing: -0.025em;
  margin: 10px 0 0;
  max-width: 520px;
}
.value-track {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  border-top: 1px solid var(--line);
}
.value-item {
  min-height: 116px;
  padding: 19px 14px 0;
  border-left: 1px solid var(--line);
}
.value-item:last-child {
  border-right: 1px solid var(--line);
}
.value-item span {
  display: block;
  color: var(--cyan-light);
  font-size: 12px;
  letter-spacing: 0.14em;
  margin-bottom: 22px;
}
.value-item strong {
  font-size: 14px;
  line-height: 1.3;
}

.project-grid {
  display: grid;
  grid-template-columns: 1.35fr 0.82fr 0.82fr;
  grid-template-rows: 300px 300px;
  gap: 16px;
}
.project-card {
  position: relative;
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 18px;
  overflow: hidden;
  background: #061727;
  box-shadow: 0 12px 45px rgba(0, 0, 0, 0.14);
}
.project-card-featured {
  grid-row: 1/3;
}
.project-card img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.86) saturate(0.92);
  transition:
    transform 0.5s ease,
    filter 0.5s ease;
}
.project-card:hover img {
  transform: scale(1.025);
  filter: brightness(0.95);
}
.project-shade {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    transparent 47%,
    rgba(2, 12, 22, 0.92) 100%
  );
}
.project-caption {
  position: absolute;
  left: 24px;
  right: 24px;
  bottom: 20px;
  z-index: 2;
}
.project-caption strong {
  display: block;
  font:
    600 22px/1.2 "Inter Display",
    sans-serif;
}
.project-caption span {
  display: block;
  color: #b4c8d7;
  margin-top: 4px;
  font-size: 14px;
}
.portfolio-nav-link {
  color: var(--cyan-light) !important;
}
.portfolio-entry {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 46px;
  margin-top: 22px;
  padding: 30px 34px;
  border: 1px solid rgba(22, 175, 231, 0.34);
  border-radius: 18px;
  background: linear-gradient(
    120deg,
    rgba(12, 48, 80, 0.96),
    rgba(5, 24, 43, 0.96)
  );
  box-shadow: 0 18px 54px rgba(0, 0, 0, 0.16);
  transition:
    transform 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}
.portfolio-entry:hover {
  transform: translateY(-2px);
  border-color: rgba(71, 204, 255, 0.72);
  box-shadow: 0 22px 64px rgba(0, 0, 0, 0.24);
}
.portfolio-entry-copy h3 {
  font:
    600 clamp(25px, 2.3vw, 36px)/1.08 "Inter Display",
    sans-serif;
  letter-spacing: -0.025em;
  margin: 8px 0;
}
.portfolio-entry-copy p {
  margin: 0;
  color: var(--muted);
  max-width: 620px;
}
.portfolio-entry-stats {
  display: flex;
  gap: 28px;
  color: #bbcfdd;
  white-space: nowrap;
}
.portfolio-entry-stats span {
  display: grid;
}
.portfolio-entry-stats strong {
  font:
    600 30px/1 "Inter Display",
    sans-serif;
  color: white;
}
.portfolio-entry-action {
  display: flex;
  align-items: center;
  gap: 15px;
  white-space: nowrap;
  padding: 14px 18px;
  border: 1px solid var(--cyan);
  border-radius: 10px;
  color: white;
  font-weight: 600;
}
.portfolio-entry-action b {
  color: var(--cyan-light);
  font-size: 20px;
  transition: transform 0.2s;
}
.portfolio-entry:hover .portfolio-entry-action b {
  transform: translateX(4px);
}

.composition-section {
  padding-top: 68px;
}
.composition-card {
  display: grid;
  grid-template-columns: 1.12fr 0.88fr;
  min-height: 620px;
  border: 1px solid var(--line);
  border-radius: 24px;
  overflow: hidden;
  background: linear-gradient(145deg, #0a2743, #06182c);
  box-shadow: var(--shadow);
}
.composition-photo {
  position: relative;
  min-width: 0;
  min-height: 620px;
  overflow: hidden;
}
.composition-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  filter: brightness(0.87) contrast(1.01) saturate(0.92);
}
.composition-photo::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 62%, rgba(6, 24, 44, 0.93));
}
.photo-pin {
  position: absolute;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid rgba(85, 206, 245, 0.58);
  border-radius: 999px;
  background: rgba(4, 19, 34, 0.87);
  backdrop-filter: blur(9px);
  font-size: 13px;
}
.photo-pin::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--cyan-light);
  box-shadow: 0 0 16px var(--cyan);
}
.pin-roof {
  left: 19%;
  top: 16%;
}
.pin-facade {
  left: 63%;
  top: 44%;
}
.pin-terrace {
  left: 46%;
  bottom: 14%;
}
.composition-copy {
  padding: 64px 58px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.composition-copy > .section-title {
  font-size: clamp(42px, 3.3vw, 56px);
}
.composition-copy > p {
  font-size: 18px;
  color: #abc2d3;
  margin: 22px 0 0;
}
.architecture-list {
  list-style: none;
  margin: 30px 0 0;
  padding: 0;
  display: grid;
  gap: 17px;
}
.architecture-list li {
  display: grid;
  grid-template-columns: 38px 1fr;
  gap: 14px;
}
.architecture-list li > span {
  color: var(--cyan-light);
  font-size: 12px;
  border-top: 1px solid var(--cyan);
  padding-top: 5px;
}
.architecture-list strong {
  display: block;
}
.architecture-list p {
  font-size: 13px;
  color: var(--muted);
  margin: 4px 0 0;
}

.services-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.service-card {
  display: grid;
  grid-template-columns: 0.92fr 1.08fr;
  min-height: 340px;
  border: 1px solid var(--line);
  border-radius: 20px;
  overflow: hidden;
  background: linear-gradient(145deg, #0b2743, #071a2e);
  transition:
    transform 0.25s ease,
    border-color 0.25s ease,
    box-shadow 0.25s ease;
}
.service-card:hover {
  transform: translateY(-3px);
  border-color: rgba(85, 206, 245, 0.5);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
}
.service-media {
  min-width: 0;
  overflow: hidden;
}
.service-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.81) saturate(0.9);
  transition: transform 0.4s ease;
}
.service-card:hover .service-media img {
  transform: scale(1.025);
}
.service-body {
  padding: 34px;
  display: flex;
  flex-direction: column;
}
.service-number {
  font-size: 12px;
  letter-spacing: 0.13em;
  color: #6f91aa;
  margin-bottom: 17px;
}
.service-body h3 {
  font:
    600 26px/1.13 "Inter Display",
    sans-serif;
  letter-spacing: -0.02em;
  margin: 0 0 13px;
}
.service-body p {
  color: #aec5d5;
  font-size: 15px;
  margin: 0 0 23px;
}
.service-body a {
  color: var(--cyan-light);
  font-weight: 600;
  font-size: 14px;
  margin-top: auto;
  align-self: flex-start;
}

.ai-shell {
  border: 1px solid var(--line-strong);
  border-radius: 24px;
  background:
    radial-gradient(
      circle at 78% 24%,
      rgba(24, 121, 180, 0.17),
      transparent 26%
    ),
    linear-gradient(145deg, #0b2947, #071a2f);
  padding: 42px;
  box-shadow: var(--shadow);
}
.ai-heading {
  display: flex;
  justify-content: space-between;
  gap: 30px;
  align-items: flex-start;
  margin-bottom: 34px;
}
.ai-heading p {
  color: #acc2d3;
  max-width: 760px;
  font-size: 18px;
  margin: 17px 0 0;
}
.prototype-badge {
  display: inline-flex;
  padding: 9px 13px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  color: #bfe9f9;
  font-size: 13px;
  white-space: nowrap;
  background: rgba(8, 35, 59, 0.6);
}
.ai-steps {
  display: grid;
  grid-template-columns: 1fr 0.76fr 1.16fr;
  gap: 18px;
}
.ai-card {
  min-width: 0;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(3, 18, 33, 0.46);
}
.step-title {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #cde3ef;
  font-size: 14px;
  margin-bottom: 14px;
}
.step-title > span {
  color: var(--cyan-light);
  font:
    600 19px/1 "Inter Display",
    sans-serif;
}
.upload-preview,
.result-preview {
  height: 350px;
  position: relative;
  overflow: hidden;
  border-radius: 14px;
  background: #03101d;
}
.upload-preview img,
.result-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.upload-preview img {
  filter: brightness(0.63) saturate(0.8);
}
.upload-preview::after {
  content: "";
  position: absolute;
  inset: 45% 0 0;
  background: linear-gradient(transparent, rgba(1, 10, 18, 0.9));
  pointer-events: none;
}
.upload-preview button {
  position: absolute;
  z-index: 2;
  left: 16px;
  right: 16px;
  bottom: 16px;
  height: 48px;
  border: 1px solid rgba(85, 206, 245, 0.48);
  border-radius: 9px;
  background: rgba(3, 22, 38, 0.82);
  color: white;
  font-weight: 600;
}
.upload-preview button:hover {
  border-color: var(--cyan-light);
}
.field-error {
  color: #ffc2c2;
  font-size: 13px;
  margin: 10px 0 0;
}
.mode-options {
  display: grid;
  gap: 10px;
}
.mode-options button {
  padding: 17px;
  text-align: left;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: #0b2946;
  color: #e7f1f7;
  transition: 0.2s;
}
.mode-options button:hover,
.mode-options button.is-selected {
  border-color: #42c5f2;
  background: linear-gradient(145deg, #164c73, #0b2a47);
  box-shadow: inset 0 0 0 1px rgba(66, 197, 242, 0.15);
}
.mode-options strong {
  display: block;
  font-size: 16px;
  margin-bottom: 4px;
}
.mode-options span {
  display: block;
  font-size: 13px;
  color: #8eb1c8;
}
.generate-button {
  width: 100%;
  margin-top: 12px;
}
.result-preview img {
  filter: brightness(0.8) saturate(0.9);
  transition: filter 0.25s;
}
.result-preview.is-loading img {
  filter: brightness(0.35) blur(2px);
}
.result-status {
  position: absolute;
  left: 14px;
  bottom: 14px;
  padding: 7px 10px;
  border-radius: 7px;
  background: rgba(3, 18, 33, 0.82);
  font-size: 12px;
  color: #c7e8f5;
}
.disclaimer {
  font-size: 13px;
  color: #87a9bf;
  margin: 12px 0 0;
}
.lead-panel {
  display: grid;
  grid-template-columns: 0.58fr 1.42fr;
  gap: 36px;
  margin-top: 28px;
  padding-top: 28px;
  border-top: 1px solid var(--line);
}
.lead-panel h3 {
  font:
    600 28px/1.15 "Inter Display",
    sans-serif;
  margin: 11px 0 9px;
}
.lead-panel > div > p {
  color: var(--muted);
  font-size: 14px;
  margin: 0;
}
.lead-form {
  display: grid;
  grid-template-columns: 1fr 1fr auto;
  gap: 12px;
  align-items: end;
}
.lead-form label {
  display: grid;
  gap: 7px;
  color: #c7dbe7;
  font-size: 13px;
}
.lead-form input,
.lead-form textarea {
  width: 100%;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: #061a2d;
  color: white;
  padding: 12px 13px;
}
.lead-form input {
  height: 49px;
}
.lead-form textarea {
  resize: vertical;
}
.lead-form input::placeholder,
.lead-form textarea::placeholder {
  color: #708ea4;
}
.lead-wishes {
  grid-column: 1/3;
}
.lead-form > .button {
  grid-column: 3;
  grid-row: 1/3;
}
.form-notice {
  grid-column: 1/-1;
  color: #a8dff2;
  font-size: 13px;
  margin: 0;
}

.included-section {
  background: linear-gradient(
    180deg,
    rgba(7, 26, 45, 0.12),
    rgba(4, 17, 31, 0.34)
  );
}
.included-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 11px;
}
.included-card {
  min-width: 0;
  min-height: 210px;
  padding: 23px 18px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: linear-gradient(
    180deg,
    rgba(13, 45, 77, 0.68),
    rgba(7, 26, 45, 0.55)
  );
}
.included-card > span {
  display: block;
  color: var(--cyan-light);
  font-size: 12px;
  letter-spacing: 0.14em;
  margin-bottom: 31px;
}
.included-card h3 {
  font:
    600 16px/1.25 "Inter Display",
    sans-serif;
  margin: 0 0 9px;
}
.included-card p {
  color: #91adbf;
  font-size: 13px;
  margin: 0;
}

.cases-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.case-card {
  min-width: 0;
  min-height: 540px;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  border: 1px solid var(--line);
  border-radius: 22px;
  overflow: hidden;
  background: linear-gradient(145deg, #0b2947, #071a2e);
}
.case-photo {
  min-width: 0;
  min-height: 540px;
}
.case-photo img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: brightness(0.76) saturate(0.9);
}
.case-body {
  padding: 42px 35px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.case-body h3 {
  font:
    600 34px/1.1 "Inter Display",
    sans-serif;
  letter-spacing: -0.025em;
  margin: 10px 0 19px;
}
.case-facts {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 22px;
}
.case-facts span {
  padding: 7px 10px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  color: #bce5f5;
  font-size: 12px;
}
.case-body ul {
  padding-left: 19px;
  color: #adc4d4;
  font-size: 15px;
  margin: 0 0 24px;
}
.case-body li {
  margin: 7px 0;
}
.case-body a {
  color: var(--cyan-light);
  font-weight: 600;
  margin-top: auto;
  font-size: 14px;
}

.process-section {
  background: rgba(3, 16, 29, 0.14);
}
.process-list {
  list-style: none;
  margin: 42px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
}
.process-list li {
  position: relative;
  padding: 0 21px;
}
.process-list li:not(:last-child)::after {
  content: "";
  position: absolute;
  top: 26px;
  left: 72px;
  right: -2px;
  border-top: 1px dashed rgba(120, 179, 214, 0.32);
}
.process-number {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line-strong);
  border-radius: 50%;
  background: #082139;
  color: var(--cyan-light);
  font:
    600 13px/1 "Inter Display",
    sans-serif;
  position: relative;
  z-index: 2;
}
.process-list strong {
  display: block;
  margin: 18px 0 7px;
  font-size: 15px;
}
.process-list p {
  font-size: 13px;
  color: #91adbf;
  margin: 0;
}

.final-cta {
  padding: 82px 0;
  background:
    radial-gradient(
      circle at 75% 40%,
      rgba(25, 117, 175, 0.2),
      transparent 29%
    ),
    linear-gradient(180deg, #071d34, #041321);
  border-top: 1px solid rgba(130, 191, 226, 0.12);
}
.final-layout {
  display: grid;
  grid-template-columns: 1.16fr 0.84fr;
  gap: 54px;
  align-items: center;
}
.final-layout h2 {
  font:
    700 clamp(43px, 3.7vw, 61px)/1.04 "Inter Display",
    sans-serif;
  letter-spacing: -0.04em;
  margin: 12px 0 15px;
  max-width: 760px;
}
.final-layout p {
  font-size: 18px;
  color: #a9c0d1;
  margin: 0 0 22px;
}
.final-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}
.site-footer {
  padding: 29px 0;
  background: #03101d;
  border-top: 1px solid rgba(130, 191, 226, 0.1);
}
.footer-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 30px;
  color: #8ea7ba;
  font-size: 13px;
}
.footer-row img {
  width: 150px;
  mix-blend-mode: screen;
  opacity: 0.84;
}
.footer-row p {
  margin: 0;
  text-align: right;
}

@media (max-width: 1200px) {
  .nav-links {
    gap: 20px;
  }
  .project-grid {
    grid-template-columns: 1.2fr 1fr;
    grid-template-rows: 340px 240px 240px;
  }
  .project-card-featured {
    grid-row: 1/2;
    grid-column: 1/3;
  }
  .services-grid {
    grid-template-columns: 1fr;
  }
  .service-card {
    min-height: 330px;
  }
  .ai-steps {
    grid-template-columns: 1fr 1fr;
  }
  .ai-result {
    grid-column: 1/3;
  }
  .included-grid {
    grid-template-columns: repeat(3, 1fr);
  }
  .cases-grid {
    grid-template-columns: 1fr;
  }
  .case-card {
    grid-template-columns: 1fr 1fr;
  }
  .final-actions {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 1024px) {
  .hero {
    grid-template-columns: 1fr;
    min-height: auto;
  }
  .hero-copy {
    padding: 65px 32px 54px;
  }
  .hero-media {
    min-height: 560px;
  }
  .value-layout {
    grid-template-columns: 1fr;
    gap: 36px;
  }
  .portfolio-entry {
    grid-template-columns: 1fr auto;
  }
  .portfolio-entry-stats {
    grid-row: 2;
  }
  .portfolio-entry-action {
    grid-row: 1/3;
    grid-column: 2;
  }
  .composition-card {
    grid-template-columns: 1fr;
  }
  .composition-photo {
    min-height: 560px;
  }
  .composition-photo::after {
    background: linear-gradient(180deg, transparent 74%, rgba(6, 24, 44, 0.88));
  }
  .lead-panel {
    grid-template-columns: 1fr;
  }
  .process-list {
    grid-template-columns: 1fr 1fr;
    gap: 34px 0;
  }
  .process-list li:not(:last-child)::after {
    display: none;
  }
  .final-layout {
    grid-template-columns: 1fr;
  }
  .final-actions {
    grid-template-columns: max-content max-content;
  }
}
@media (max-width: 820px) {
  .container {
    width: min(100% - 40px, 680px);
  }
  .section {
    padding: 82px 0;
  }
  .section-head {
    display: grid;
    gap: 18px;
  }
  .nav-row {
    height: 74px;
  }
  .brand {
    width: 164px;
  }
  .mobile-toggle {
    display: block;
  }
  .nav-links {
    position: absolute;
    top: 74px;
    left: 0;
    right: 0;
    display: none;
    padding: 17px 20px 22px;
    background: rgba(4, 17, 31, 0.98);
    border-bottom: 1px solid var(--line);
    flex-direction: column;
    align-items: stretch;
    gap: 0;
  }
  .nav-links.is-open {
    display: flex;
  }
  .nav-links > a:not(.button) {
    padding: 14px 2px;
  }
  .nav-links > a:not(.button)::after {
    display: none;
  }
  .nav-links .button {
    margin-top: 10px;
  }
  .hero-copy {
    padding: 54px 24px 46px;
  }
  .hero-title {
    font-size: clamp(46px, 9vw, 64px);
  }
  .hero-media {
    min-height: 480px;
  }
  .value-track {
    grid-template-columns: repeat(2, 1fr);
  }
  .value-item:last-child {
    grid-column: 1/3;
  }
  .project-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: 380px 240px 240px;
  }
  .project-card-featured {
    grid-column: 1/3;
  }
  .composition-copy {
    padding: 48px 32px;
  }
  .service-card {
    grid-template-columns: 1fr;
  }
  .service-media {
    height: 340px;
  }
  .ai-shell {
    padding: 28px;
  }
  .ai-heading {
    display: grid;
  }
  .prototype-badge {
    width: max-content;
  }
  .ai-steps {
    grid-template-columns: 1fr;
  }
  .ai-result {
    grid-column: auto;
  }
  .lead-form {
    grid-template-columns: 1fr 1fr;
  }
  .lead-wishes {
    grid-column: 1/3;
  }
  .lead-form > .button {
    grid-column: 1/3;
    grid-row: auto;
  }
  .case-card {
    grid-template-columns: 1fr;
  }
  .case-photo {
    min-height: 430px;
  }
  .final-actions {
    grid-template-columns: 1fr 1fr;
  }
  .footer-row {
    flex-wrap: wrap;
  }
  .footer-row p {
    text-align: left;
  }
}
@media (max-width: 560px) {
  body {
    font-size: 16px;
  }
  .container {
    width: calc(100% - 32px);
  }
  .section {
    padding: 68px 0;
  }
  .section-title {
    font-size: 38px;
  }
  .glow-line {
    width: 42px;
  }
  .hero-copy {
    padding: 45px 18px 39px;
  }
  .hero-title {
    font-size: 43px;
  }
  .hero-subtitle {
    font-size: 17px;
  }
  .hero-actions {
    display: grid;
  }
  .hero-actions .button {
    width: 100%;
  }
  .phone-row {
    display: grid;
    gap: 10px;
  }
  .phone-row a {
    font-size: 17px;
  }
  .hero-media {
    min-height: 390px;
  }
  .hero-media img {
    object-position: 100% center;
    transform: scale(1.08);
  }
  .image-label {
    right: 14px;
    bottom: 14px;
  }
  .value-section {
    padding: 52px 0;
  }
  .value-track {
    grid-template-columns: 1fr;
  }
  .value-item {
    min-height: auto;
    padding: 16px;
    border-right: 1px solid var(--line);
    display: flex;
    align-items: center;
    gap: 18px;
  }
  .value-item:last-child {
    grid-column: auto;
  }
  .value-item span {
    margin: 0;
    min-width: 28px;
  }
  .project-grid {
    display: grid;
    grid-template-columns: 1fr;
    grid-template-rows: 340px repeat(4, 230px);
  }
  .project-card-featured {
    grid-column: auto;
  }
  .portfolio-entry {
    display: grid;
    grid-template-columns: 1fr;
    gap: 24px;
    padding: 25px 22px;
  }
  .portfolio-entry-stats {
    grid-row: auto;
    gap: 22px;
  }
  .portfolio-entry-action {
    grid-row: auto;
    grid-column: auto;
    justify-content: center;
  }
  .composition-card {
    width: calc(100% - 24px);
  }
  .composition-photo {
    min-height: 400px;
  }
  .photo-pin {
    font-size: 11px;
    padding: 7px 9px;
  }
  .pin-roof {
    left: 8%;
    top: 12%;
  }
  .pin-facade {
    left: 58%;
    top: 43%;
  }
  .pin-terrace {
    left: 32%;
    bottom: 12%;
  }
  .composition-copy {
    padding: 38px 24px;
  }
  .composition-copy > .section-title {
    font-size: 38px;
  }
  .service-media {
    height: 280px;
  }
  .service-body {
    padding: 28px 24px;
  }
  .ai-shell {
    width: calc(100% - 20px);
    padding: 21px 14px;
    border-radius: 20px;
  }
  .ai-heading .section-title {
    font-size: 37px;
  }
  .prototype-badge {
    white-space: normal;
  }
  .upload-preview,
  .result-preview {
    height: 300px;
  }
  .lead-form {
    grid-template-columns: 1fr;
  }
  .lead-wishes,
  .lead-form > .button {
    grid-column: auto;
  }
  .included-grid {
    grid-template-columns: 1fr;
  }
  .included-card {
    min-height: auto;
  }
  .cases-grid {
    width: calc(100% - 8px);
    margin-inline: auto;
  }
  .case-photo {
    min-height: 340px;
  }
  .case-body {
    padding: 32px 24px;
  }
  .case-body h3 {
    font-size: 31px;
  }
  .process-list {
    grid-template-columns: 1fr;
    gap: 25px;
  }
  .process-list li {
    display: grid;
    grid-template-columns: 54px 1fr;
    gap: 16px;
    padding: 0;
  }
  .process-list strong {
    margin: 4px 0;
  }
  .final-cta {
    padding: 68px 0;
  }
  .final-layout h2 {
    font-size: 42px;
  }
  .final-actions {
    grid-template-columns: 1fr;
  }
  .footer-row {
    display: grid;
    justify-items: start;
  }
  .footer-row p {
    text-align: left;
  }
}
@media (max-width: 380px) {
  .hero-title {
    font-size: 39px;
  }
  .section-title,
  .composition-copy > .section-title,
  .ai-heading .section-title {
    font-size: 35px;
  }
  .button {
    padding-inline: 16px;
  }
  .case-body h3 {
    font-size: 29px;
  }
}
@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition: none !important;
  }
}

.preview-modal {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: none;
  overflow: auto;
  background: #081b33;
}
.preview-modal.is-open {
  display: block;
}
.preview-modal-content {
  min-height: 100%;
  background: #081b33;
}
.preview-shadow-host {
  display: block;
  min-height: 100%;
}
.preview-modal-close {
  position: fixed;
  z-index: 3;
  right: 22px;
  bottom: 22px;
  width: 48px;
  height: 48px;
  border: 1px solid rgba(85, 206, 245, 0.7);
  border-radius: 50%;
  background: rgba(3, 16, 29, 0.92);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  color: #fff;
  font-size: 25px;
  line-height: 1;
}
.preview-source {
  display: none;
}
.preview-label {
  position: fixed;
  z-index: 49;
  left: 14px;
  bottom: 14px;
  padding: 7px 10px;
  border: 1px solid rgba(85, 206, 245, 0.32);
  border-radius: 7px;
  background: rgba(3, 16, 29, 0.78);
  color: #9fb7ca;
  font-size: 11px;
  backdrop-filter: blur(8px);
  pointer-events: none;
}
@media (max-width: 560px) {
  .preview-label {
    display: none;
  }
  .preview-modal-close {
    right: 14px;
    bottom: 14px;
  }
}
@media print {
  .site-header,
  .preview-label,
  .preview-modal {
    display: none !important;
  }
}
